// Lost responses consume durable read opportunities; never renew a spent Apply.
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn execution_lost_reconciliation_polls_stop_after_three_leases_and_restarts_do_not_renew_them(){
    let(mut c,work,_)=submission_fixture().await;let key=format!("apply_work:{}",work["id"].as_str().unwrap());let mut unknown=work.clone();unknown["status"]=json!("unknown");unknown["stage"]=json!("SUBMISSION_UNKNOWN");unknown["lease_token"]=Value::Null;unknown["lease_until"]=Value::Null;browser_save(&mut c,&key,unknown).await;automated_apply_agents::execution::submission::recover_unknown(&mut c,false).await.unwrap();sqlx::query("UPDATE owner_preferences SET value=jsonb_set(value,'{available_at}','\"2000-01-01T00:00:00Z\"') WHERE key=$1").bind(&key).execute(&mut c).await.unwrap();
    for attempt in 1..=3{let claimed=automated_apply_agents::execution::queue::claim(&mut c,"naukri",&json!({"worker":"fictional_lost_poll"}),Some(&["reconcile_application"])).await.unwrap().unwrap();assert_eq!(claimed["reconciliation_lease_attempts"],attempt);assert_eq!(claimed["admitted_actions"],work["admitted_actions"]);let mut expired=claimed;expired["lease_until"]=json!("2000-01-01T00:00:00Z");browser_save(&mut c,&key,expired).await;}
    assert!(automated_apply_agents::execution::queue::claim(&mut c,"naukri",&json!({"worker":"fictional_restart"}),Some(&["reconcile_application"])).await.unwrap().is_none());let exhausted=browser_pref(&mut c,&key).await;assert_eq!(exhausted["status"],"unknown");assert_eq!(exhausted["stage"],"SUBMISSION_UNKNOWN");assert_eq!(exhausted["reason"],"bounded_reconciliation_exhausted");assert_eq!(exhausted["reconciliation_lease_attempts"],3);assert_eq!(exhausted["admitted_actions"],work["admitted_actions"]);automated_apply_agents::execution::submission::recover_unknown(&mut c,false).await.unwrap();assert_eq!(browser_pref(&mut c,&key).await,exhausted);
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn execution_reconciliation_admissions_are_bounded_even_when_a_single_lease_continues_without_report_counts(){
    let(mut c,work,_)=submission_fixture().await;let key=format!("apply_work:{}",work["id"].as_str().unwrap());let mut current=work.clone();current["status"]=json!("leased");browser_save(&mut c,&key,current.clone()).await;let packets=packet_settings();let resumes=sync_resume_settings();
    for attempt in 1..=3{let admitted=automated_apply_agents::execution::admission::admit(&mut c,sync_request(&current),automated_apply_agents::execution::admission::Services{packets:&packets,resumes:&resumes}).await.unwrap();assert_eq!(admitted["reconciliation_read_admissions"],attempt);assert_eq!(admitted["admitted_actions"],work["admitted_actions"]);current=admitted;current["status"]=json!("leased");current["revision"]=json!(current["revision"].as_i64().unwrap()+1);browser_save(&mut c,&key,current.clone()).await;}
    let before=browser_snapshot(&mut c).await;assert_eq!(automated_apply_agents::execution::admission::admit(&mut c,sync_request(&current),automated_apply_agents::execution::admission::Services{packets:&packets,resumes:&resumes}).await.unwrap_err(),Failure("bounded_reconciliation_exhausted"));assert_eq!(browser_snapshot(&mut c).await,before);assert_eq!(sqlx::query_scalar::<_,i64>("SELECT count(*) FROM owner_preferences WHERE starts_with(key,'apply_budget:')").fetch_one(&mut c).await.unwrap(),0);
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn execution_reconciliation_dropped_claim_event_does_not_spend_a_lease_or_change_original_admissions(){
    let(mut c,work,_)=submission_fixture().await;let key=format!("apply_work:{}",work["id"].as_str().unwrap());let mut queued=work.clone();queued["status"]=json!("queued");queued["lease_token"]=Value::Null;queued["lease_until"]=Value::Null;browser_save(&mut c,&key,queued).await;let before=browser_snapshot(&mut c).await;sqlx::raw_sql("CREATE FUNCTION fixture_reconciliation_claim_drop() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF starts_with(NEW.key,'apply_event:') THEN RETURN NULL; END IF; RETURN NEW; END $$;CREATE TRIGGER fixture_reconciliation_claim_drop BEFORE INSERT ON owner_preferences FOR EACH ROW EXECUTE FUNCTION fixture_reconciliation_claim_drop()").execute(&mut c).await.unwrap();assert_eq!(automated_apply_agents::execution::queue::claim(&mut c,"naukri",&json!({"worker":"fictional_read"}),Some(&["reconcile_application"])).await.unwrap_err(),Failure("execution_write_ack_failed"));assert_eq!(browser_snapshot(&mut c).await,before);sqlx::raw_sql("DROP TRIGGER fixture_reconciliation_claim_drop ON owner_preferences;DROP FUNCTION fixture_reconciliation_claim_drop()").execute(&mut c).await.unwrap();
}
